export interface ConnectorConfig {
  /** Datadog API key for authentication (DD-API-KEY header) */
  datadogApiKey: string;
  /** Datadog Application key for authentication (DD-APPLICATION-KEY header) */
  datadogAppKey: string;
  /** Datadog site (e.g., 'datadoghq.com', 'us3.datadoghq.com') */
  datadogSite: string;
  /** Optional fetch implementation for testing */
  fetch?: typeof fetch;
}

export interface Mailchimp429Payload {
  /** HTTP status code (always 429 for this trigger) */
  status_code: number;
  /** Retry-After header value in seconds */
  retry_after: number;
  /** Summary of final outcome after retries */
  final_outcome: string;
  /** Error details from the last failed attempt */
  error_message: string;
}

export interface HandleResult {
  /** Datadog event ID from the response */
  eventId: string;
  /** Datadog event URL from the response */
  eventUrl: string;
}

export async function handle(
  payload: Mailchimp429Payload,
  config: ConnectorConfig
): Promise<HandleResult> {
  // Validate required payload fields
  if (payload.status_code === undefined || payload.status_code === null) {
    throw new Error('Missing required field: status_code');
  }
  if (payload.retry_after === undefined || payload.retry_after === null) {
    throw new Error('Missing required field: retry_after');
  }
  if (!payload.final_outcome) {
    throw new Error('Missing required field: final_outcome');
  }
  if (!payload.error_message) {
    throw new Error('Missing required field: error_message');
  }

  // Validate status code is 429
  if (payload.status_code !== 429) {
    throw new Error(`Expected status_code 429, got ${payload.status_code}`);
  }

  // Validate required config
  if (!config.datadogApiKey) {
    throw new Error('Missing required config: datadogApiKey');
  }
  if (!config.datadogAppKey) {
    throw new Error('Missing required config: datadogAppKey');
  }
  if (!config.datadogSite) {
    throw new Error('Missing required config: datadogSite');
  }

  const fetchImpl = config.fetch ?? fetch;

  // Build Datadog event payload per field mapping and API spec
  const eventPayload = {
    title: payload.final_outcome,
    text: payload.error_message,
    tags: ['mailchimp', 'rate_limit', 'retry'],
    date: Date.now(),
    priority: 'normal' as const,
    source_type_name: 'Mailchimp',
  };

  const url = `https://event-management-intake.${config.datadogSite}/api/v2/events`;

  const response = await fetchImpl(url, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'DD-API-KEY': config.datadogApiKey,
      'DD-APPLICATION-KEY': config.datadogAppKey,
    },
    body: JSON.stringify(eventPayload),
  });

  if (!response.ok) {
    const errorText = await response.text().catch(() => '');
    throw new Error(`Datadog API error: ${response.status} ${response.statusText} for POST ${url} - ${errorText}`);
  }

  const result = await response.json() as { id: string; url: string };

  return {
    eventId: result.id,
    eventUrl: result.url,
  };
}

